+ // Click cookie banner if present (non-fatal)
+ await clickIfVisible(page, '#onetrust-accept-btn-handler', { timeout: 1500 });
+ await clickIfVisible(page, "button[aria-label='Accept all']", { timeout: 1000 });
+ // Close potential geo/country modal
+ await clickIfVisible(page, "button[aria-label='Close']", { timeout: 1000 });
+ // Wait for PLP grid or tiles to appear, with incremental scrolling
+ const plpTargets = ["ul[data-testid='plp-grid'] li", "[data-component='ProductTile']", "article[data-test='product-card']"];

+ await waitForAnySelector(page, plpTargets, { timeout: 8000 }).catch(async () => {
+   await autoScrollUntil(page, async () => await anyVisible(page, plpTargets), { maxScrolls: 8, stepPx: 1200 });
+   return waitForAnySelector(page, plpTargets, { timeout: 4000 });
+ });

+ const itemSel = "ul[data-testid='plp-grid'] li, [data-component='ProductTile'], article[data-test='product-card']";
+ const linkSel = "a[data-testid='product-link'], a.c-product-tile__link, a[href^='/'][href*='/women/'], a[href^='https://www.moncler.com/']";
+ const tiles = await page.$$(itemSel);
+ const pdpLinks = await Promise.all(tiles.map(async t => {
+   const a = await t.$(linkSel);
+   return a ? page.evaluate(el => (el as HTMLAnchorElement).href, a) : null;
+ }));
+ return pdpLinks.filter(Boolean);

+ export function normalizeMonclerUrl(u: URL) {
+   if (u.hostname === 'www.moncler.com') {
+     u.pathname = u.pathname.replace(/\/en-gb\/en-[a-z-]+\//, '/en-gb/');
+     u.pathname = u.pathname.replace(/\/(en-[a-z-]+)\/(en-[a-z-]+)\//, '/$1/');
+     if (!u.pathname.startsWith('/en-gb/')) {
+       u.pathname = '/en-gb/' + u.pathname.replace(/^\/+/, '');
+     }
+   }
+   return u;
+ }
